INSERT INTO `alerts` VALUES (1,'Quezon City Rainfall Advisory','Moderate to heavy intermittent rain expected in Novaliches and Diliman districts over the next 48 hours. Ensure field drainage channels are clear.','warning','climate','All','active','AgriTech Dev Team','2026-10-27 13:19:21','2026-10-27 13:19:21'),(2,'Harvest Window Reminder: Pechay Batch','Pechay plots planted 25 days ago have reached optimal leaf canopy. Begin harvesting before heavy rain cycle to avoid leaf rot.','info','harvest','Pechay','active','AgriTech Dev Team','2026-10-27 13:19:21','2026-10-27 13:19:21');
